import { describe, expect, it } from "vitest";
import { isUsableTimeZone, usableTimeZone } from "./timezone.js";

/**
 * `tenants.timezone` is not picked from a list — it comes out of a résumé
 * parse, so the column holds whatever the document said.
 *
 * Production, 2026-08-21: Cristiane's row read `America/Sao_Paulo (UTC-3)`,
 * copied verbatim from her CV. `tenantTimezone` handed it straight to
 * `Intl.DateTimeFormat`, which throws a `RangeError` — and that did not
 * mislabel a date, it killed **the whole apply stage**: `stage apply failed:
 * Invalid time zone specified: America/Sao_Paulo (UTC-3)`. An account with
 * thirty approved applications submitted nothing, and the message named a
 * clock rather than anything a reader would connect to applying.
 */
describe("isUsableTimeZone", () => {
  it("rejects the exact string that took production down", () => {
    expect(isUsableTimeZone("America/Sao_Paulo (UTC-3)")).toBe(false);
  });

  it("rejects the other shapes a document offers", () => {
    for (const raw of [
      "",
      "   ",
      null,
      undefined,
      "UTC-3",
      "GMT-3",
      "Horário de Brasília",
    ]) {
      expect(isUsableTimeZone(raw), `${raw}`).toBe(false);
    }
  });

  it("accepts real zones, including the ones this product uses", () => {
    for (const tz of [
      "America/Sao_Paulo",
      "Europe/London",
      "America/Toronto",
      "UTC",
    ]) {
      expect(isUsableTimeZone(tz), tz).toBe(true);
    }
  });

  it("tolerates surrounding whitespace rather than failing on it", () => {
    expect(isUsableTimeZone("  America/Sao_Paulo  ")).toBe(true);
  });

  /**
   * A bare offset IS a zone `Intl` accepts, and this must not "helpfully"
   * reject it: the job is to keep unusable strings away from `Intl`, not to
   * impose a house style on the ones that work.
   */
  it("accepts a plain offset, which the runtime does support", () => {
    expect(isUsableTimeZone("-03:00")).toBe(true);
  });
});

describe("usableTimeZone", () => {
  it("returns the caller's fallback for anything unusable", () => {
    // The fallback is deliberately the caller's: a quota window falls back to
    // the column default so a cap keeps its meaning, while a label falls back
    // to UTC and says UTC.
    expect(
      usableTimeZone("America/Sao_Paulo (UTC-3)", "America/Sao_Paulo"),
    ).toBe("America/Sao_Paulo");
    expect(usableTimeZone(null, "UTC")).toBe("UTC");
  });

  it("returns the zone itself when it is usable, trimmed", () => {
    expect(usableTimeZone(" Europe/London ", "UTC")).toBe("Europe/London");
  });

  it("never throws, whatever it is handed", () => {
    for (const raw of ["}{", "America/Nowhere", ""]) {
      expect(() => usableTimeZone(raw, "UTC")).not.toThrow();
      expect(usableTimeZone(raw, "UTC")).toBe("UTC");
    }
  });
});
